entries[27985] = { ["name"] = "Schwebend", ["text"] = "100 Mana\nReagenzien:\nLeichte Feder\nErlaubt es Euch, einige Handbreit über dem Boden zu schweben. Während Ihr schwebt, fallt Ihr mit geringerer Geschwindigkeit, und könnt über wasserartige Oberflächen reisen." }
