entries[27987] = { ["name"] = "Unheilige Aura", ["text"] = "Sofort\nDer Zaubernde verursacht automatisch alle 2 Sek. 150 Schattenschaden bei in der Nähe befindlichen Feinden. Die Aura hält an, bis die Aktion abgebrochen wird." }
